"use client"

import React, { useState, useEffect } from "react"
import { FileText, TrendingUp, AlertTriangle, CheckCircle, Clock, Users, Filter, X } from "lucide-react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { PageLayout } from "@/components/page-layout"
import { fetchReports, type Report } from "@/lib/api"

interface ReportData {
  summary: {
    totalReviewed: number
    totalViolations: number
    aiAccuracy: number
    avgResponseTime: number
  }
  weeklyTrend: {
    day: string
    count: number
    violations: number
  }[]
  violationTypes: {
    type: string
    count: number
    percentage: number
  }[]
}

interface DailyStats {
  date: string
  totalReviewed: number
  violations: number
  aiJudged: number
}

export default function ReportPage() {
  const [reports, setReports] = useState<Report[]>([])
  const [loading, setLoading] = useState(true)
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize, setPageSize] = useState(10)
  const [total, setTotal] = useState(0)
  const [totalPages, setTotalPages] = useState(0)
  const [filterStatus, setFilterStatus] = useState<string>("all")
  const [searchQuery, setSearchQuery] = useState("")
  const [showFilters, setShowFilters] = useState(false)

  // 模拟统计数据（这部分在实际项目中应该从API获取）
  const reportData: ReportData = {
    summary: {
      totalReviewed: 495,
      totalViolations: 51,
      aiAccuracy: 93.27,
      avgResponseTime: 0.3
    },
    weeklyTrend: [
      { day: "周一", count: 102, violations: 10 },
      { day: "周二", count: 88, violations: 6 },
      { day: "周三", count: 110, violations: 15 },
      { day: "周四", count: 95, violations: 8 },
      { day: "周五", count: 100, violations: 12 },
    ],
    violationTypes: [
      { type: "广告推广", count: 21, percentage: 41 },
      { type: "水贴灌水", count: 18, percentage: 35 },
      { type: "违规内容", count: 12, percentage: 24 },
    ]
  }

  // 模拟每日统计数据（这部分在实际项目中应该从API获取）
  const dailyStats: DailyStats[] = [
    {
      date: "2025-11-25",
      totalReviewed: 100,
      violations: 12,
      aiJudged: 70,
    },
    {
      date: "2025-11-24",
      totalReviewed: 95,
      violations: 8,
      aiJudged: 65,
    },
    {
      date: "2025-11-23",
      totalReviewed: 110,
      violations: 15,
      aiJudged: 78,
    },
    {
      date: "2025-11-22",
      totalReviewed: 88,
      violations: 6,
      aiJudged: 60,
    },
    {
      date: "2025-11-21",
      totalReviewed: 102,
      violations: 10,
      aiJudged: 72,
    },
  ]

  const loadReports = async () => {
    setLoading(true)
    try {
      const response = await fetchReports(currentPage, pageSize, filterStatus)
      if (response.code === 200) {
        setReports(response.data.records)
        setTotal(response.data.total)
        setTotalPages(response.data.totalPages)
      }
    } catch (error) {
      console.error("获取举报数据失败:", error)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadReports()
  }, [currentPage, pageSize, filterStatus])

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page)
    }
  }

  const handlePageSizeChange = (size: number) => {
    setPageSize(size)
    setCurrentPage(1)
  }

  const handleFilterStatusChange = (status: string) => {
    setFilterStatus(status)
    setCurrentPage(1)
  }

  const getStatusText = (status: string) => {
    switch (status) {
      case 'pending':
        return '待处理'
      case 'processed':
        return '已处理'
      case 'dismissed':
        return '已驳回'
      default:
        return status
    }
  }

  const getStatusClass = (status: string) => {
    switch (status) {
      case 'pending':
        return 'bg-yellow-100 text-yellow-800'
      case 'processed':
        return 'bg-green-100 text-green-800'
      case 'dismissed':
        return 'bg-gray-100 text-gray-800'
      default:
        return 'bg-gray-100 text-gray-800'
    }
  }

  return (
    <PageLayout title="审核报告">
      <div className="max-w-5xl mx-auto px-6 py-6 space-y-6">
        {/* Search and Filter */}
        <div className="space-y-3">
          <div className="flex gap-2">
            <div className="relative flex-1">
              <Input
                placeholder="搜索举报内容..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="bg-gray-100 border-0 rounded-xl"
              />
              {searchQuery && (
                <button 
                  className="absolute right-3 top-1/2 -translate-y-1/2" 
                  onClick={() => setSearchQuery("")}
                >
                  <X className="h-4 w-4 text-gray-400" />
                </button>
              )}
            </div>
            <Button
              variant="outline"
              size="icon"
              className={`rounded-xl ${showFilters ? "bg-primary-blue text-white" : ""}`}
              onClick={() => setShowFilters(!showFilters)}
            >
              <Filter className="h-4 w-4" />
            </Button>
          </div>

          {/* Filter Options */}
          {showFilters && (
            <div className="bg-white p-4 rounded-xl shadow-sm space-y-3">
              <div>
                <p className="text-sm font-medium text-gray-700 mb-2">状态筛选</p>
                <div className="flex flex-wrap gap-2">
                  <Button
                    variant={filterStatus === "all" ? "default" : "outline"}
                    size="sm"
                    className={`rounded-full text-xs ${filterStatus === "all" ? "bg-primary-blue" : ""}`}
                    onClick={() => handleFilterStatusChange("all")}
                  >
                    全部
                  </Button>
                  <Button
                    variant={filterStatus === "pending" ? "default" : "outline"}
                    size="sm"
                    className={`rounded-full text-xs ${filterStatus === "pending" ? "bg-primary-blue" : ""}`}
                    onClick={() => handleFilterStatusChange("pending")}
                  >
                    待处理
                  </Button>
                  <Button
                    variant={filterStatus === "processed" ? "default" : "outline"}
                    size="sm"
                    className={`rounded-full text-xs ${filterStatus === "processed" ? "bg-primary-blue" : ""}`}
                    onClick={() => handleFilterStatusChange("processed")}
                  >
                    已处理
                  </Button>
                  <Button
                    variant={filterStatus === "dismissed" ? "default" : "outline"}
                    size="sm"
                    className={`rounded-full text-xs ${filterStatus === "dismissed" ? "bg-primary-blue" : ""}`}
                    onClick={() => handleFilterStatusChange("dismissed")}
                  >
                    已驳回
                  </Button>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Reports List */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <AlertTriangle className="h-5 w-5 text-amber-500" />
              举报列表
            </CardTitle>
          </CardHeader>
          <CardContent>
            {loading ? (
              <div className="p-8 text-center text-gray-500">
                <p>加载中...</p>
              </div>
            ) : reports.length === 0 ? (
              <div className="p-8 text-center text-gray-500">
                <p>没有找到匹配的举报</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-gray-100">
                      <th className="text-left py-3 px-2 font-medium text-gray-500">举报人</th>
                      <th className="text-left py-3 px-2 font-medium text-gray-500">举报类型</th>
                      <th className="text-left py-3 px-2 font-medium text-gray-500">内容标题</th>
                      <th className="text-left py-3 px-2 font-medium text-gray-500">举报原因</th>
                      <th className="text-left py-3 px-2 font-medium text-gray-500">状态</th>
                      <th className="text-left py-3 px-2 font-medium text-gray-500">举报时间</th>
                    </tr>
                  </thead>
                  <tbody>
                    {reports.map((report) => (
                      <tr key={report.reportId} className="border-b border-gray-50 hover:bg-gray-50">
                        <td className="py-3 px-2 text-gray-900">{report.reporter}</td>
                        <td className="py-3 px-2 text-gray-900">
                          {report.targetType === 'post' ? '帖子' : report.targetType}
                        </td>
                        <td className="py-3 px-2 text-gray-900">{report.targetTitle}</td>
                        <td className="py-3 px-2 text-gray-900">{report.reason}</td>
                        <td className="py-3 px-2">
                          <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getStatusClass(report.status)}`}>
                            {getStatusText(report.status)}
                          </span>
                        </td>
                        <td className="py-3 px-2 text-gray-500">
                          {new Date(report.createdAt).toLocaleDateString()}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                
                {/* Pagination Controls */}
                <div className="flex items-center justify-between p-4 border-t border-gray-100">
                  <div className="flex items-center gap-2">
                    <span className="text-sm text-gray-600">
                      显示第 {(currentPage - 1) * pageSize + 1} 到 {Math.min(currentPage * pageSize, total)} 条，共 {total} 条记录
                    </span>
                    <div className="flex items-center gap-1 ml-4">
                      <span className="text-sm text-gray-600">每页:</span>
                      <select 
                        value={pageSize}
                        onChange={(e) => handlePageSizeChange(Number(e.target.value))}
                        className="border border-gray-300 rounded-md px-2 py-1 text-sm"
                      >
                        <option value="5">5</option>
                        <option value="10">10</option>
                        <option value="20">20</option>
                        <option value="50">50</option>
                      </select>
                    </div>
                  </div>
                  
                  <div className="flex items-center gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handlePageChange(currentPage - 1)}
                      disabled={currentPage <= 1}
                      className="rounded-full"
                    >
                      上一页
                    </Button>
                    
                    <div className="flex items-center">
                      <span className="text-sm text-gray-600 mx-2">
                        第 {currentPage} 页，共 {totalPages} 页
                      </span>
                    </div>
                    
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handlePageChange(currentPage + 1)}
                      disabled={currentPage >= totalPages}
                      className="rounded-full"
                    >
                      下一页
                    </Button>
                  </div>
                </div>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Summary Cards */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <Card>
            <CardContent className="p-4 text-center">
              <div className="w-12 h-12 bg-blue-100 rounded-xl flex items-center justify-center mx-auto mb-3">
                <FileText className="h-6 w-6 text-primary-blue" />
              </div>
              <p className="text-2xl font-bold text-gray-900">{reportData.summary.totalReviewed}</p>
              <p className="text-sm text-gray-500">总审核量</p>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="p-4 text-center">
              <div className="w-12 h-12 bg-red-100 rounded-xl flex items-center justify-center mx-auto mb-3">
                <AlertTriangle className="h-6 w-6 text-red-500" />
              </div>
              <p className="text-2xl font-bold text-gray-900">{reportData.summary.totalViolations}</p>
              <p className="text-sm text-gray-500">违规内容</p>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="p-4 text-center">
              <div className="w-12 h-12 bg-green-100 rounded-xl flex items-center justify-center mx-auto mb-3">
                <CheckCircle className="h-6 w-6 text-green-500" />
              </div>
              <p className="text-2xl font-bold text-gray-900">{reportData.summary.aiAccuracy}%</p>
              <p className="text-sm text-gray-500">AI准确率</p>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="p-4 text-center">
              <div className="w-12 h-12 bg-amber-100 rounded-xl flex items-center justify-center mx-auto mb-3">
                <Clock className="h-6 w-6 text-amber-500" />
              </div>
              <p className="text-2xl font-bold text-gray-900">{reportData.summary.avgResponseTime}s</p>
              <p className="text-sm text-gray-500">平均响应</p>
            </CardContent>
          </Card>
        </div>

        {/* Weekly Trend */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <TrendingUp className="h-5 w-5 text-primary-blue" />
              本周审核趋势
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {reportData.weeklyTrend.map((day, index) => (
                <div key={index} className="flex items-center gap-4">
                  <span className="text-sm text-gray-600 w-12">{day.day}</span>
                  <div className="flex-1 flex items-center gap-2">
                    <div className="flex-1 h-6 bg-gray-100 rounded-full overflow-hidden relative">
                      <div
                        className="h-full bg-primary-blue rounded-full"
                        style={{ width: `${(day.count / 120) * 100}%` }}
                      />
                      <div
                        className="absolute top-0 left-0 h-full bg-red-400 rounded-full"
                        style={{ width: `${(day.violations / 120) * 100}%` }}
                      />
                    </div>
                  </div>
                  <div className="text-right w-24">
                    <span className="text-sm font-medium text-gray-900">{day.count}</span>
                    <span className="text-xs text-gray-400"> / </span>
                    <span className="text-sm text-red-500">{day.violations}</span>
                  </div>
                </div>
              ))}
            </div>
            <div className="flex items-center gap-6 mt-4 pt-4 border-t border-gray-100">
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 bg-primary-blue rounded-full" />
                <span className="text-xs text-gray-500">总审核量</span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 bg-red-400 rounded-full" />
                <span className="text-xs text-gray-500">违规数量</span>
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Violation Types */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <AlertTriangle className="h-5 w-5 text-amber-500" />
              违规类型分布
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {reportData.violationTypes.map((type, index) => (
                <div key={index} className="space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="text-sm font-medium text-gray-700">{type.type}</span>
                    <span className="text-sm text-gray-500">
                      {type.count} 件 ({type.percentage}%)
                    </span>
                  </div>
                  <div className="h-3 bg-gray-100 rounded-full overflow-hidden">
                    <div
                      className={`h-full rounded-full ${
                        index === 0 ? "bg-red-400" : index === 1 ? "bg-amber-400" : "bg-orange-400"
                      }`}
                      style={{ width: `${type.percentage}%` }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Daily Stats Table */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Users className="h-5 w-5 text-primary-blue" />
              每日审核明细
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-gray-100">
                    <th className="text-left py-3 px-2 font-medium text-gray-500">日期</th>
                    <th className="text-right py-3 px-2 font-medium text-gray-500">审核量</th>
                    <th className="text-right py-3 px-2 font-medium text-gray-500">违规</th>
                    <th className="text-right py-3 px-2 font-medium text-gray-500">AI判断</th>
                    <th className="text-right py-3 px-2 font-medium text-gray-500">违规率</th>
                  </tr>
                </thead>
                <tbody>
                  {dailyStats.map((stat, index) => (
                    <tr key={index} className="border-b border-gray-50 hover:bg-gray-50">
                      <td className="py-3 px-2 text-gray-900">{stat.date}</td>
                      <td className="py-3 px-2 text-right text-gray-900">{stat.totalReviewed}</td>
                      <td className="py-3 px-2 text-right text-red-500">{stat.violations}</td>
                      <td className="py-3 px-2 text-right text-primary-blue">{stat.aiJudged}</td>
                      <td className="py-3 px-2 text-right text-gray-500">
                        {((stat.violations / stat.totalReviewed) * 100).toFixed(1)}%
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </CardContent>
        </Card>
      </div>
    </PageLayout>
  )
}